import styled from "styled-components"
import { Search, User, ShoppingCart } from "lucide-react"

export default function Home() {
    return (
        <HomeStyled>
            <NavBar>
                <h1>Juice</h1>
                <ContainerNavigation>
                    <button>Menu</button>
                    <button>About</button>
                    <button>Our specials</button>
                    <button>Our locations</button>
                    <button>Blog</button>
                </ContainerNavigation>
                <ContainerUser>
                    <button><Search /></button>
                    <button><ShoppingCart /></button>
                    <button><User /></button>
                </ContainerUser>
            </NavBar>
            <ContainerContent>
                <header>
                    Faster juice delivery service
                </header>
                <Title>
                    Juice to make your day Fresh
                </Title>
                <Descrição>
                    Stay cool this summer as fruit jucies and Drinks are available online.
                </Descrição>
                <Interativos>
                    <Cart><ShoppingCart color="white" /></Cart>
                    <AddToCart>ADD TO CART</AddToCart>
                    <HowItWorks>HOW IT WORKS</HowItWorks>
                </Interativos>
            </ContainerContent>
        </HomeStyled>
    )
}

const HomeStyled = styled.main`
position: absolute;
width: 100%;
height: 100%;
`
const NavBar = styled.header`
position: fixed;
width: 100%;
height: 100px;
display: flex;
justify-content: space-around;
align-items: center;
`
const ContainerNavigation = styled.div`
width: 40%;
height: 50px;
display: flex;
align-items: center;
justify-content: space-around;

button {
    background-color:white;
    border: solid 1px white;
    min-width: 70px;
    height: 40px;
    border-top-left-radius: 30px;
    border-bottom-left-radius: 30px;
    border-top-right-radius: 30px;
    border-bottom-right-radius: 30px;
}

button:hover {
    border: solid 1px gray;
    transform: scale(1.05);
}
`
const ContainerUser = styled.div`
width: 10%;
height: 50px;
display: flex;
align-items: center;
justify-content:space-around ;

button {
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}
`
const ContainerContent = styled.div`
margin-top: 130px;
width: 50%;
height: 40%;
margin-left: 75px;
display: flex;
flex-direction: column;
justify-content: space-around;

header {
    max-width: 60%;
    height: 30%;
    display: flex;
    align-items: center;
    justify-content: center;
    border-top-left-radius: 30px;
    border-bottom-left-radius: 30px;
    border-top-right-radius: 30px;
    border-bottom-right-radius: 30px;
    background-color: beige;
    font-size: 20px;
}
`
const Title = styled.span`
font-size: 70px;
`
const Descrição = styled.span`
font-size: 20px;
color: gray;
`
const Interativos = styled.div`
width: 100%;
height: 50px;
display: flex;
align-items: center;
gap: 20px;
`
const AddToCart = styled.button`
color: white;
border: none;
background-color: orange;
width: 30%;
height: 50px;
border-top-left-radius: 30px;
border-bottom-left-radius: 30px;
border-top-right-radius: 30px;
border-bottom-right-radius: 30px;
`
const HowItWorks = styled.button`
border-color: orange;
color: orange;
width: 30%;
height: 50px;
border-top-left-radius: 30px;
border-bottom-left-radius: 30px;
border-top-right-radius: 30px;
border-bottom-right-radius: 30px;
`
const Cart = styled.div`
width: 50px;
height: 50px;
display: flex;
align-items: center;
justify-content: center;
border-radius: 50%;
background-color: orange;
`
